import{_ as l,a0 as p,w as d,s as o,I as a,x as n,a1 as i,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"三步上手 GDB | LCTT x X-CMD","titleTemplate":false,"description":"三步上手 GDB | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三步上手 GDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三步上手 GDB | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20140210 Three steps to learning GDB","title":"三步上手 GDB","tag":"201801","desc":""},"relativePath":"201801/20140210 Three steps to learning GDB.md","filePath":"[post].md"}'),g={name:"201801/20140210 Three steps to learning GDB.md"};function h(b,s,k,c,u,f){const e=p("Link");return d(),o("div",null,[s[27]||(s[27]=a("h1",{id:"三步上手-gdb",tabindex:"-1"},[n("三步上手 GDB "),a("a",{class:"header-anchor",href:"#三步上手-gdb","aria-label":"Permalink to “三步上手 GDB”"},"​")],-1)),a("p",null,[s[1]||(s[1]=n("調試 C 程序，曾讓我很困擾。然而當我之前在寫我的",-1)),i(e,{href:"https://jvns.ca/blog/categories/kernel"},{default:t(()=>[...s[0]||(s[0]=[n("操作系統",-1)])]),_:1}),s[2]||(s[2]=n("時，我有很多的 Bug 需要調試。我很幸運的使用上了 qemu 模擬器，它允許我將調試器附加到我的操作系統。這個調試器就是 ",-1)),s[3]||(s[3]=a("code",null,"gdb",-1)),s[4]||(s[4]=n("。",-1))]),s[28]||(s[28]=r(`<p>我得解釋一下，你可以使用 <code>gdb</code> 先做一些小事情，因為我發現初學它的時候真的很混亂。我們接下來會在一個小程序中，設置斷點，查看內存。.</p><h3 id="_1、-設斷點" tabindex="-1">1、 設斷點 <a class="header-anchor" href="#_1、-設斷點" aria-label="Permalink to “1、 設斷點”">​</a></h3><p>如果你曾經使用過調試器，那你可能已經會設置斷點了。</p><p>下面是一個我們要調試的程序（雖然沒有任何 Bug）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void do_thing() {</span></span>
<span class="line"><span>    printf(&quot;Hi!\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>    do_thing();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>另存為 <code>hello.c</code>. 我們可以使用 <code>dbg</code> 調試它，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bork@kiwi ~&gt; gcc -g hello.c -o hello</span></span>
<span class="line"><span>bork@kiwi ~&gt; gdb ./hello</span></span></code></pre></div><p>以上是帶調試信息編譯 <code>hello.c</code>（為了 <code>gdb</code> 可以更好工作），並且它會給我們醒目的提示符，就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb)</span></span></code></pre></div><p>我們可以使用 <code>break</code> 命令設置斷點，然後使用 <code>run</code> 開始調試程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) break do_thing </span></span>
<span class="line"><span>Breakpoint 1 at 0x4004f8</span></span>
<span class="line"><span>(gdb) run</span></span>
<span class="line"><span>Starting program: /home/bork/hello </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Breakpoint 1, 0x00000000004004f8 in do_thing ()</span></span></code></pre></div><p>程序暫停在了 <code>do_thing</code> 開始的地方。</p><p>我們可以通過 <code>where</code> 查看我們所在的調用棧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) where</span></span>
<span class="line"><span>#0  do_thing () at hello.c:3</span></span>
<span class="line"><span>#1  0x08050cdb in main () at hello.c:6</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><h3 id="_2、-閲讀彙編代碼" tabindex="-1">2、 閲讀彙編代碼 <a class="header-anchor" href="#_2、-閲讀彙編代碼" aria-label="Permalink to “2、 閲讀彙編代碼”">​</a></h3><p>使用 <code>disassemble</code> 命令，我們可以看到這個函數的彙編代碼。棒級了，這是 x86 彙編代碼。雖然我不是很懂它，但是 <code>callq</code> 這一行是 <code>printf</code> 函數調用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) disassemble do_thing</span></span>
<span class="line"><span>Dump of assembler code for function do_thing:</span></span>
<span class="line"><span>   0x00000000004004f4 &lt;+0&gt;:     push   %rbp</span></span>
<span class="line"><span>   0x00000000004004f5 &lt;+1&gt;:     mov    %rsp,%rbp</span></span>
<span class="line"><span>=&gt; 0x00000000004004f8 &lt;+4&gt;:     mov    $0x40060c,%edi</span></span>
<span class="line"><span>   0x00000000004004fd &lt;+9&gt;:     callq  0x4003f0 </span></span>
<span class="line"><span>   0x0000000000400502 &lt;+14&gt;:    pop    %rbp</span></span>
<span class="line"><span>   0x0000000000400503 &lt;+15&gt;:    retq</span></span></code></pre></div><p>你也可以使用 <code>disassemble</code> 的縮寫 <code>disas</code>。</p><h3 id="_3、-查看內存" tabindex="-1">3、 查看內存 <a class="header-anchor" href="#_3、-查看內存" aria-label="Permalink to “3、 查看內存”">​</a></h3><p>當調試我的內核時，我使用 <code>gdb</code> 的主要原因是，以確保內存佈局是如我所想的那樣。檢查內存的命令是 <code>examine</code>，或者使用縮寫 <code>x</code>。我們將使用<code>x</code>。</p><p>通過閲讀上面的彙編代碼，似乎 <code>0x40060c</code> 可能是我們所要打印的字符串地址。我們來試一下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/s 0x40060c</span></span>
<span class="line"><span>0x40060c:        &quot;Hi!&quot;</span></span></code></pre></div><p>的確是這樣。<code>x/s</code> 中 <code>/s</code> 部分，意思是“把它作為字符串展示”。我也可以“展示 10 個字符”，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) x/10c 0x40060c</span></span>
<span class="line"><span>0x40060c:       72 &#39;H&#39;  105 &#39;i&#39; 33 &#39;!&#39;  0 &#39;\\000&#39;        1 &#39;\\001&#39;        27 &#39;\\033&#39;       3 &#39;\\003&#39;        59 &#39;;&#39;</span></span>
<span class="line"><span>0x400614:       52 &#39;4&#39;  0 &#39;\\000&#39;</span></span></code></pre></div><p>你可以看到前四個字符是 <code>H</code>、<code>i</code>、<code>!</code> 和 <code>\\0</code>，並且它們之後的是一些不相關的東西。</p>`,25)),a("p",null,[s[6]||(s[6]=n("我知道 ",-1)),s[7]||(s[7]=a("code",null,"gdb",-1)),s[8]||(s[8]=n(" 很多其他的東西，但是我仍然不是很瞭解它，其中 ",-1)),s[9]||(s[9]=a("code",null,"x",-1)),s[10]||(s[10]=n(" 和 ",-1)),s[11]||(s[11]=a("code",null,"break",-1)),s[12]||(s[12]=n(" 讓我獲得很多。你還可以閲讀 ",-1)),i(e,{href:"https://ftp.gnu.org/old-gnu/Manuals/gdb-5.1.1/html_chapter/gdb_9.html#SEC56"},{default:t(()=>[...s[5]||(s[5]=[n("do umentation for examining memory",-1)])]),_:1}),s[13]||(s[13]=n("。",-1))]),s[29]||(s[29]=a("hr",null,null,-1)),a("p",null,[s[15]||(s[15]=n("via: ",-1)),i(e,{href:"https://jvns.ca/blog/2014/02/10/three-steps-to-learning-gdb/"},{default:t(()=>[...s[14]||(s[14]=[n("https://jvns.ca/blog/2014/02/10/three-steps-to-learning-gdb/",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("作者：",-1)),i(e,{href:"https://jvns.ca"},{default:t(()=>[...s[16]||(s[16]=[n("Julia Evans",-1)])]),_:1}),s[20]||(s[20]=n(" 譯者：",-1)),i(e,{href:"https://github.com/Torival"},{default:t(()=>[...s[17]||(s[17]=[n("Torival",-1)])]),_:1}),s[21]||(s[21]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[22]||(s[22]=[n("LCTT",-1)])]),_:1}),s[25]||(s[25]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[23]||(s[23]=[n("Linux中國",-1)])]),_:1}),s[26]||(s[26]=n(" 榮譽推出",-1))])])}const v=l(g,[["render",h]]);export{C as __pageData,v as default};
